export type Alumni = {
  id: string;
  name: string;
  avatar: string;
  batch: number;
  degree: string;
  role: string;
  company: string;
  location: string;
  industry: string;
  linkedin: string;
  github?: string;
  bio: string;
  skills: string[];
  achievements?: string[];
  email: string;
  is_featured?: number;
};

export type Student = {
  id: string;
  name: string;
  avatar: string;
  year: string;
  major: string;
  linkedin: string;
  github: string;
  bio: string;
  skills: string[];
  lookingFor: string;
};

export type MentorVideo = {
  id: string;
  title: string;
  thumbnail: string;
  mentor: string;
  mentorAvatar: string;
  mentorRole?: string;
  mentorNote?: string;
  channelName?: string;
  recommendedFor?: string;
  referralType?: "mentor_referral" | "alumni_talk";
  duration: string;
  views: number;
  topic: string;
  postedAgo: string;
  description: string;
  youtubeUrl: string;
  youtubeId: string;
};

export type MentorPlaylist = {
  id: string;
  title: string;
  topic: string;
  mentor: string;
  mentorAvatar: string;
  mentorRole: string;
  mentorBatch: string;
  whyCurated: string;
  thumbnails: string[];
  videoIds: string[];
  totalDuration: string;
  videoCount: number;
  studentsFollowing: number;
};

export type Doubt = {
  id: string;
  student: string;
  studentAvatar: string;
  question: string;
  topic: string;
  replies: number;
  status: "open" | "answered";
  postedAgo: string;
};

